  if child: v+=F(mass(child),mass(s))*value(child,(t,))[0]
 first_losses[names[t]]=float(v)
v,a=value(s,())
nxt={}
if a in names:
 t=names.index(a)
 for y in (0,1):
  child=tuple(i for i in s if rows[i][2][t]==y)
  nxt[str(y)]=value(child,(t,))[1] if child else 'IMPOSSIBLE'
artifact={'first':a,'first_losses':first_losses,'next':nxt}
