from fractions import Fraction as F
import json
# V=0 is a single observation; the repeated display is not independent evidence.
rows=[('A',15,(1,0,1)),('B',6,(1,0,0)),('B',5,(0,1,0)),('D',14,(0,0,0))]
repairs='ABCD'; tests='TUW'
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
costs=[F('0.8'),F('1.2'),F('7.4')]
def mass(rs): return sum(r[1] for r in rs)
def risk(rs,a): return F(sum(w*loss[repairs.index(a)][repairs.index(m)] for m,w,_ in rs),mass(rs))
def best(rs): return min((risk(rs,a),a) for a in repairs)
posterior={a:float(F(sum(w for m,w,_ in rows if m==a),mass(rows))) for a in repairs}
remaining={a:risk(rows,a) for a in repairs}
branches={}
for t,c in zip(tests,costs):
 j=tests.index(t); v=c; branch={}
 for y in (0,1):
  rs=[r for r in rows if r[2][j]==y]
  if rs:
   val,a=best(rs); v+=F(mass(rs),mass(rows))*val; branch[str(y)]=a
  else: branch[str(y)]='IMPOSSIBLE'
 remaining[t]=v; branches[t]=branch
v,a=min((v,a) for a,v in remaining.items())
# Independent arithmetic checks: immediate A=11*24/40+14*6/40=8.7;
# T outcomes: 1 chooses A (144 weighted loss), 0 chooses B (112 weighted loss).
assert remaining['A']==F(87,10)
assert remaining['T']==F('0.8')+F(144+112,40)==F('7.2')
# W separates A perfectly from B/D, whose best repair B loses 14*8.
assert remaining['W']==F('7.4')+F(112,40)==F('10.2')
artifact={'posterior':posterior,'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':a,'repair_after':branches.get(a,{})}
payload=json.dumps(artifact)
assert json.loads(payload)==artifact
print(payload)

